dims={name:{(h,w),(w,h)} for name,h,w in pieces}
allp=[]
for name,h,w in pieces:
 for hh,ww in dims[name]:
  for r in range(20-hh+1):
   for c in range(8-ww+1):
    cells=frozenset((rr,cc) for rr in range(r,r+hh) for cc in range(c,c+ww))
    if cells<=mask: allp.append((name,r,c,cells,hh,ww))
sols=[]
def search(covered, used, chosen):
 if len(used)==len(pieces):
  if covered==mask: sols.append(chosen[:])
  return
 unc=mask-covered; best=None; opts_best=None
 for cell in unc:
  opts=[p for p in allp if p[0] not in used and cell in p[3] and not(p[3]&covered)]
  if not opts:return
  if opts_best is None or len(opts)<len(opts_best):best,opts_best=cell,opts
  if len(opts_best)==1:break
 for p in opts_best:
  search(covered|p[3],used|{p[0]},chosen+[p])
  if len(sols)>=20:return
